/* ICU AND YOU — verification markers. GENERATED by make_verification.py.
   Edit verification.json, not this file.

   <sup class="vf" data-v="id"></sup> after a number becomes click-to-open,
   and a page listed in P gets a band saying every number on it was checked.
   Deliberately unlike the glossary: a raised mark AFTER a number, not a
   dotted underline UNDER a word, so the two systems never read as one. */
(function(){
  var V = {"adr-concentrations": {"c": "1:1000 is 1 mg/mL; 1:10,000 is 0.1 mg/mL", "s": "Definitional, and consistent with ASCIA Guidelines: Acute Management of Anaphylaxis (2026)", "u": "https://www.allergy.org.au/images/ASCIA_HP_Guidelines_Acute_Management_Anaphylaxis_2026_v2.pdf", "d": "23 October 2026", "r": null, "v": "confirmed", "n": ""}, "adr-anaphylaxis": {"c": "Anaphylaxis, intramuscular: 10 microgram/kg to a maximum of 500 microgram — 0.01 mL/kg of 1:1000", "s": "ASCIA Guidelines: Acute Management of Anaphylaxis (2026), which gives 0.01 mg/kg up to 0.5 mg per dose", "u": "https://www.allergy.org.au/images/ASCIA_HP_Guidelines_Acute_Management_Anaphylaxis_2026_v2.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "adr-autoinjector": {"c": "Autoinjectors: 0.15 mg for 7.5–20 kg, 0.3 mg from 20 kg, 0.5 mg from 50 kg", "s": "ASCIA Guidelines: Adrenaline (Epinephrine) Device Prescription (2026), and the Royal Children's Hospital anaphylaxis guideline, which agree on 7.5–20 kg, over 20 kg and over 50 kg", "u": "https://www.allergy.org.au/images/stories/anaphylaxis/2025/ASCIA_HP_Guidelines_Adrenaline_Device_Prescription_2026.pdf", "d": "23 October 2026", "r": "October 2027", "v": "corrected", "n": "The page previously read 0.15 mg from about 15 kg and 0.3 mg from about 30 kg. Both thresholds were too high, and the 0.5 mg band was missing. Corrected 23 October 2026."}, "adr-arrest": {"c": "Cardiac arrest, intravenous or intraosseous: 10 microgram/kg — 0.1 mL/kg of 1:10,000, every three to five minutes", "s": "Royal Children's Hospital, Adrenaline and fluid bolus administration in resuscitation, which gives 0.1 mL/kg of 1:10,000 = 10 microgram/kg", "u": "https://www.rch.org.au/rchcpg/hospital_clinical_guideline_index/Adrenaline_and_fluid_bolus_administration_in_resuscitation/", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": "RCH states a four-minute interval; three to five minutes is the international convention and is retained."}, "adr-shock": {"c": "Shock, infusion: titrated from about 0.05 microgram/kg/min", "s": "Perth Children's Hospital adrenaline medication monograph, which gives \"initially 0.05–0.1 microgram/kg/minute, then titrate according to response\" from birth to 18 years", "u": "https://pch.health.wa.gov.au/~/media/Files/Hospitals/PCH/General-documents/Health-professionals/MedicationMonographs/Adrenaline.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "adr-croup": {"c": "Croup, nebulised: 5 mg — 5 mL of 1:1000, every age and weight", "s": "Children's Health Queensland, which states \"in all ages/weights, the adrenaline dose will be 5mg via nebuliser\", and the Royal Children's Hospital croup guideline, which gives a flat 5 mL of 1:1000 and no mL/kg", "u": "https://www.childrens.health.qld.gov.au/__data/assets/pdf_file/0034/193669/Adrenaline-Use-Croup.pdf", "d": "23 October 2026", "r": "October 2027", "v": "corrected", "n": "The page previously gave 0.5 mL/kg of 1:1000 to a maximum of 5 mL, the long-standing weight-based form. Two major Australian paediatric services have moved to a flat dose. The two agree at 10 kg and above, where the formula hits the cap; below that the flat dose gives roughly twice as much, which is the point of the change — what reaches an inflamed larynx does not scale with body weight. Changed 23 October 2026."}, "par-conc": {"c": "Intravenous paracetamol is 10 mg/mL, supplied as 500 mg in 50 mL and 1,000 mg in 100 mL", "s": "Perth Children's Hospital paracetamol monograph, which gives the IV infusion as 1 g/100 mL (10 mg/mL)", "u": "https://pch.health.wa.gov.au/~/media/Files/Hospitals/PCH/General-documents/Health-professionals/MedicationMonographs/Paracetamol.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": "PCH stocks only the 1 g/100 mL presentation; both are registered in Australia, so formularies vary. The concentration, which is the number that matters for the tenfold error, is the same in both."}, "par-oral": {"c": "Oral or rectal, child: 15 mg/kg every four to six hours, maximum 60 mg/kg/day", "s": "Perth Children's Hospital paracetamol monograph: \"15 mg/kg (up to 1000 mg) every 4-6 hours\", \"maximum of 60 mg/kg (up to 4000 mg) per day\"", "u": "https://pch.health.wa.gov.au/~/media/Files/Hospitals/PCH/General-documents/Health-professionals/MedicationMonographs/Paracetamol.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "par-iv-large": {"c": "Intravenous, over 10 kg: 15 mg/kg every six hours, maximum 60 mg/kg/day", "s": "Perth Children's Hospital paracetamol monograph: \"15 mg/kg (up to 1000 mg) every 6 hours\", \"maximum of 60 mg/kg (up to 4000 mg) per day\"", "u": "https://pch.health.wa.gov.au/~/media/Files/Hospitals/PCH/General-documents/Health-professionals/MedicationMonographs/Paracetamol.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "par-iv-small": {"c": "Intravenous, 10 kg or less: 7.5 mg/kg every four to six hours, maximum 30 mg/kg/day", "s": "NSW TAG position statement addendum, which records that \"the TGA approved dose for infants < 10 kg is now 7.5 mg/kg/dose 4-6 hourly (max 30 mg/kg/day)\" — and then recommends against it, supporting 15 mg/kg (max 60 mg/kg/day)", "u": "https://www.nswtag.org.au/wp-content/uploads/2017/07/paracetamol-iv-addendum-dec-2012.pdf", "d": "23 October 2026", "r": "October 2027", "v": "contested", "n": "The page previously gave this as every six hours; the product information says four to six. More importantly it presented the PI dose as simply the dose. NSW TAG and Perth Children's Hospital both recommend 15 mg/kg here instead, so the two differ twofold. The page now says so rather than picking a side quietly."}, "par-threshold": {"c": "An acute ingestion of 200 mg/kg or 10 g, whichever is less, is potentially toxic", "s": "Chiew et al, Updated guidelines for the management of paracetamol poisoning in Australia and New Zealand, MJA 2020, Box 1: \"= 10 g or = 200 mg/kg (whichever is less)\"", "u": "https://aci.health.nsw.gov.au/__data/assets/pdf_file/0005/558527/MJA-Guidelines-management-paracetamol-poisoning.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "par-massive": {"c": "For modified-release preparations, 500 mg/kg or 30 g is a massive overdose with absorption up to 24 hours; for immediate-release the trigger is a concentration more than double the nomogram line", "s": "Chiew et al, MJA 2020: \"All patients who ingest 30 g or more or 500 mg/kg or more of modified release paracetamol... should receive an increased dose of acetylcysteine\", and separately that an initial concentration \"greater than double the nomogram line may benefit from an increased dose\"", "u": "https://aci.health.nsw.gov.au/__data/assets/pdf_file/0005/558527/MJA-Guidelines-management-paracetamol-poisoning.pdf", "d": "23 October 2026", "r": "October 2027", "v": "corrected", "n": "The page previously read \"Above 500 mg/kg or 30 g is a massive overdose, where absorption may continue for up to twenty-four hours and increased acetylcysteine doses are used\", with no mention of modified release. That threshold is specific to modified-release preparations. For immediate-release the guideline sets no dose threshold at all — the decision is made on the concentration. Corrected 23 October 2026."}, "par-nac": {"c": "Acetylcysteine, two bags: 200 mg/kg (maximum 22 g) over four hours, then 100 mg/kg (maximum 11 g) over sixteen", "s": "Chiew et al, MJA 2020, Box 3: \"acetylcysteine 200 mg/kg (maximum 22 g)\" over 4 hours, then \"acetylcysteine 100 mg/kg (maximum 11 g)\" over 16 hours", "u": "https://aci.health.nsw.gov.au/__data/assets/pdf_file/0005/558527/MJA-Guidelines-management-paracetamol-poisoning.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": "The regimen was right; the maximum doses were missing and have been added."}, "par-duration": {"c": "Duration at maximum dose: review by 48 to 72 hours", "s": "Perth Children's Hospital paracetamol monograph, which caps the increased 90 mg/kg/day ceiling at 48 hours and advises the lowest effective dose beyond a week", "u": "https://pch.health.wa.gov.au/~/media/Files/Hospitals/PCH/General-documents/Health-professionals/MedicationMonographs/Paracetamol.pdf", "d": "23 October 2026", "r": "October 2027", "v": "confirmed", "n": "Practice guidance rather than a guideline threshold. No Australian source sets a hard 48-to-72-hour limit at the standard maximum dose; the monograph's explicit 48-hour cap applies to the raised 90 mg/kg/day ceiling. The page's framing as a review point, not a stop, is a fair reading."}, "scad-inverse": {"c": "The genetics of SCAD run opposite to those of coronary artery disease: six colocalised loci with opposite risk alleles, and a negative genome-wide genetic correlation of -0.12", "s": "Adlam, Berrandou, Georges et al, Nature Genetics 2023;55:964-972 - \"several associated variants have diametrically opposite associations with CAD\"; colocalisation at six loci (posterior probability 84-100%), all with opposite risk alleles; rg = -0.12 +/- 0.04, P = 3.7e-3. Elevated blood pressure was the only shared genetic risk factor; BMI, lipids, type 2 diabetes and smoking showed no effect on SCAD risk", "u": "https://www.nature.com/articles/s41588-023-01410-1", "d": "26 October 2026", "r": null, "v": "confirmed", "n": "The direction is confirmed and the mechanism is better evidenced than the episode states it - COL4A1/COL4A2 raises SCAD risk with higher collagen IV expression and CAD risk with lower. But the strength is not: a correlation of -0.12 is weak, and does not support the guest's stronger claim that the two diseases do not co-exist. The page says so."}, "scad-share": {"c": "SCAD's share of heart attacks in women under 50 is reported as 4-5%, about 25%, up to 35%, and about 1%, depending on the source", "s": "Kovacic on this episode (4-5%); Victor Chang Cardiac Research Institute (about 25%); JACC State-of-the-Art Review 2020;76:961-984 (up to 35% of ACS in women under 50, flagged in the same text as single-centre and for ACS rather than MI, with Californian discharge data giving about 0.98% of women presenting with AMI); and Raphael et al, JACC 2025, which puts atherothrombosis at 47% of infarcts in women up to 65", "u": "https://www.jacc.org/doi/10.1016/j.jacc.2020.05.084", "d": "26 October 2026", "r": "October 2027", "v": "contested", "n": "Genuinely unsettled, and the guest states both a maximal and a minimal version within two sentences. The claim that SCAD is the most common cause of MI in women under 50 is made by Kovacic here and by Sharonne Hayes in the ACC's own magazine, but no published figure places it above atherothrombosis. The page presents the spread rather than picking a number."}, "scad-peripartum": {"c": "SCAD is the single commonest cause of heart attack around the time of childbirth, accounting for 15 to 43% of pregnancy-associated infarcts", "s": "American College of Cardiology, \"Hidden in Plain Sight\", August 2025, citing Hayes 2020 and Milani 2025: SCAD accounts for 15-43% of pregnancy-associated acute MI, about 1.81 per 100,000 pregnancies, with upwards of 70% in the first postpartum week. The Victor Chang Cardiac Research Institute states the same", "u": "https://www.acc.org/Latest-in-Cardiology/Articles/2025/08/01/01/Cover-Story-Hidden-in-Plain-Sight", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "This is the qualified form of the contested claim above, and it holds. The qualifier - at the time of childbirth - is doing all the work."}, "scad-syndromic": {"c": "About 10% of SCAD patients have an identifiable syndromic connective tissue condition underneath", "s": "JACC State-of-the-Art Review 2020;76:961-984, which puts pathogenic variants in connective tissue or aortopathy genes at 5 to 9% of events, with familial SCAD under 1%", "u": "https://www.jacc.org/doi/10.1016/j.jacc.2020.05.084", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "The guest's 10% sits just above the published 5-9% and is a fair round figure for a spoken answer. Note this is a different quantity from the common-variant genetics: around twenty susceptibility genes point at collagen and matrix biology without explaining cases in a Mendelian way."}, "scad-fmd": {"c": "Fibromuscular dysplasia is found in about half of women presenting with SCAD", "s": "JACC State-of-the-Art Review 2020;76:961-984: among cohorts of more than 100 patients screened, FMD prevalence ran from 45.2% (Prasad 2015) to 77.6% (Saw 2017), with 54% (Tweet 2014) and 58% (Kok 2018) in between", "u": "https://www.jacc.org/doi/10.1016/j.jacc.2020.05.084", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "About 50% is at the conservative end of a 45 to 78% range. Screening is of the renal, carotid and other extracoronary arteries; the consensus documents recommend head-to-pelvis CT or MR angiography."}, "scad-ddimer": {"c": "A D-dimer should not be ordered without first establishing pre-test probability, and should not be ordered at all in a patient who is low-risk and PERC-negative, or who is high-risk and needs imaging regardless", "s": "Raja, Greenberg, Qaseem, Denberg, Fitterman & Schuur, \"Evaluation of Patients With Suspected Acute Pulmonary Embolism: Best Practice Advice From the Clinical Guidelines Committee of the American College of Physicians\", Ann Intern Med 2015;163:701-711 - BPA 1 (establish pre-test probability first), BPA 2 (do not order a D-dimer in low-risk patients meeting all PERC criteria) and BPA 6 (do not order a D-dimer at high pre-test probability)", "u": "https://www.acpjournals.org/doi/10.7326/M14-1772", "d": "26 October 2026", "r": "October 2027", "v": "flagged", "n": "Recorded against the guest's advice to add a D-dimer whenever a troponin is ordered. Defensible in his own setting, where pre-test probability is not low, but this episode is addressed to general practice and the advice does not generalise. The page carries the caveat."}, "scad-recurrence": {"c": "Recurrent SCAD is independently predicted by hypertension (raises risk) and beta blocker use (lowers it). Fibromuscular dysplasia is NOT an independent predictor of recurrence", "s": "Saw, Humphries, Aymong, Sedlak, Prakash, Starovoytov & Mancini, \"Spontaneous Coronary Artery Dissection: Clinical Outcomes and Risk of Recurrence\", J Am Coll Cardiol 2017;70:1148-1158. 327 patients, median follow-up 3.1 years, recurrent de novo SCAD in 10.4%. On multivariable analysis only two factors remained independent: hypertension HR 2.46 (95% CI 1.23-4.93, p=0.011) and beta blocker use HR 0.36 (95% CI 0.18-0.73, p=0.004). Fibromuscular dysplasia was not significantly associated with recurrence", "u": "https://iscadregistry.bidmc.org/images/2/28/2017_Saw_JACC_recurrence.pdf", "d": "26 October 2026", "r": "October 2027", "v": "corrected", "n": "The guest names three predictors - absent beta blocker, FMD, and untreated hypertension. Two of the three hold. FMD did not predict recurrence in this cohort, which is the study the claim derives from. The distinction favours the patient and the page makes it. His headline recurrence figure of 20-30% is also the top half of a 10-30% reported range; this cohort recorded 10.4% over three years."}, "scad-conservative": {"c": "Most SCAD is managed conservatively rather than stented - the guest says two thirds to 70%, the largest published cohort 83%", "s": "Saw et al, J Am Coll Cardiol 2017;70:1148-1158: \"the majority (83.1%) were initially treated medically\" (the Results section gives 83.2%). The JACC State-of-the-Art Review 2020 reports a 53% procedural failure rate for PCI in SCAD, which is the reason conservative management predominates", "u": "https://iscadregistry.bidmc.org/images/2/28/2017_Saw_JACC_recurrence.pdf", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "The guest's figure is lower than the published one, so if anything he understates how often SCAD is left alone. Both support the clinical point: do not stent a stable patient with flow in the vessel."}, "scad-phactr1": {"c": "The same PHACTR1 risk allele raises the risk of fibromuscular dysplasia, spontaneous coronary artery dissection, cervical artery dissection, migraine and hypertension, while the opposite allele raises the risk of coronary artery disease", "s": "Georges, Yang, Berrandou et al, \"Genetic investigation of fibromuscular dysplasia identifies risk loci and shared genetics with common cardiovascular diseases\", Nature Communications 2021;12:6031. PHACTR1 (rs9349379, P = 5e-15) is described as a pleiotropic locus involved in a large number of vascular diseases; PHACTR1 and LRP1 associate with migraine, SCAD and cervical artery dissection with the SAME risk allele as FMD; the top loci raise FMD and hypertension risk with the same alleles (rg = 0.36); and for CAD the risk alleles are opposite, with a negative genetic correlation (rg = -0.31 conditioned on systolic blood pressure). Migraine-FMD genetic correlation rg = 0.28", "u": "https://www.nature.com/articles/s41467-021-26174-2", "d": "26 October 2026", "r": null, "v": "confirmed", "n": "Confirms the guest's migraine point and, independently of the Nature Genetics 2023 paper, the inverse relationship with coronary disease. The presence of cervical artery dissection in the same allelic family is what makes his blanket advice against neck manipulation anatomical rather than merely sceptical. Note the 2021 paper does not support the previously proposed EDN1 regulatory mechanism at this locus."}, "scad-quinolone": {"c": "Fluoroquinolones carry a warning for aortic aneurysm and dissection, and should not be used in people with the genetic conditions associated with those unless no other treatment is available", "s": "FDA Drug Safety Communication, December 2018, on the fluoroquinolone class (ciprofloxacin, levofloxacin, moxifloxacin, ofloxacin, gemifloxacin). It states the drugs should not be used in people with certain genetic conditions associated with aortic aneurysm and dissection, naming Marfan, Ehlers-Danlos and Loeys-Dietz syndromes, unless no other treatment options are available. The TGA has published its own Australian advisory on the same question", "u": "https://www.tga.gov.au/news/safety-updates/fluoroquinolone-antibiotics-and-risk-aortic-aneurysmdissection", "d": "26 October 2026", "r": "October 2027", "v": "flagged", "n": "The warning is AORTIC and names three syndromes. SCAD and FMD are not among them, so the guest is extending it by analogy to an arteriopathy. The extension is reasonable - FMD is itself an arteriopathy and about 10% of SCAD patients carry one of the named syndromes - but it is an extension and the page says so. Flagged rather than confirmed because the claim as the guest states it (strongly contraindicated in all SCAD and FMD) goes beyond the source. The FDA page itself could not be read directly - rate limited on two attempts - and the wording here is taken from a secondary summary; re-read the primary at next review. The TGA page is robots-disallowed to automated fetching."}, "scad-exercise": {"c": "Published expert guidance finds no data to support restricting scuba diving, roller coasters or skydiving after SCAD, sets no weight limit in kilograms, and recommends moderate aerobic exercise 30-40 minutes 5-7 days a week plus cardiac rehabilitation for every patient", "s": "Tweet, Olin, Bonikowske, Adlam & Hayes, \"Physical Activity and Exercise in Patients With Spontaneous Coronary Artery Dissection and Fibromuscular Dysplasia\", European Heart Journal 2021;42:3825-3828. Low-resistance weight training with proper technique and avoidance of Valsalva or straining rather than a stated weight limit; caution for endurance training, muscle building, yoga with extreme head and neck positions, and high-intensity exercise in extreme environmental conditions; extreme or unusual exercise reported as a trigger in up to 29% of patients; after carotid or vertebral dissection avoid push-ups and sit-ups for 8-12 weeks", "u": "https://www.acc.org/latest-in-cardiology/ten-points-to-remember/2021/10/11/17/27/physical-activity-and-exercise-in-patients", "d": "26 October 2026", "r": "October 2027", "v": "contested", "n": "The guest's restriction list is markedly more conservative than the published guidance written by, among others, the heads of the Mayo registry and the European cohorts. He labels his own advice as intuition rather than evidence every time he gives it. Recorded as contested rather than corrected because neither position rests on trial data; the page sets them side by side and notes that the cost of each precaution falls on the patient's life, not the clinician's."}, "nn-temp": {"c": "Target newborn temperature 36.5-37.5 degrees C", "s": "ANZCOR 2021 newborn guidelines, key recommendations: maintain a temperature between 36.5 and 37.5 degrees C in non-asphyxiated infants of all gestational ages. ANZCOR Guideline 13.8 repeats the same range as the normothermia goal", "u": "https://www.neoresus.org.au/wp-content/uploads/2021/10/ANZCOR-2021-Newborn-Guidelines-Key-recommendations.pdf", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "nn-ppv": {"c": "Start positive pressure ventilation if not breathing or heart rate under 100", "s": "ANZCOR Guideline 13.4 (April 2021): start positive pressure ventilation where the newborn is apnoeic or breathing inadequately and \"the heart rate is less than 100 beats per min and not increasing\"", "u": "https://www.anzcor.org/home/neonatal-resuscitation/guideline-13-4-airway-management-and-mask-ventilation-of-the-newborn", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "Confirmed. The guideline's full wording adds \"and not increasing\", which the map compresses out. Left as it stands: a mind map is a prompt, and the rising heart rate is already the subject of the box beside it."}, "nn-pressures": {"c": "Inflation pressure about 30 cmH2O at term, 20-25 preterm, PEEP 5", "s": "ANZCOR Guideline 13.4 (April 2021): \"the suggested initial pressures are 30 cm H2O for term newborns and 20 to 25 cm H2O for premature newborns\", and for PEEP \"5 cm H2O is the suggested initial setting\"", "u": "https://www.anzcor.org/home/neonatal-resuscitation/guideline-13-4-airway-management-and-mask-ventilation-of-the-newborn", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "All three exact. The guideline's wider PEEP recommendation is to commence at 5 to 8 cmH2O with caution above 8; 5 is the stated initial setting, so the map's single figure is correct."}, "nn-rate": {"c": "Ventilation rate 40-60 per minute", "s": "ANZCOR Guideline 13.4 (April 2021): \"40 to 60 inflations per minute\", with an inspiratory time of 0.3 to 0.5 seconds", "u": "https://www.anzcor.org/home/neonatal-resuscitation/guideline-13-4-airway-management-and-mask-ventilation-of-the-newborn", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "nn-compressions": {"c": "Heart rate under 60 despite effective ventilation: compressions 3:1, 120 events a minute, two thumbs encircling", "s": "ANZCOR newborn guidelines via NeoResus: compressions are indicated when the heart rate remains below 60 bpm despite 30 seconds of effective positive pressure ventilation; ratio 3:1; approximately 120 events per minute, being 90 compressions and 30 inflations; two-thumb hand-encircling technique preferred, two-finger the alternative", "u": "https://www.neoresus.org.au/learning-resources/key-concepts/first-response/circulation/", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "Every element exact, including the arithmetic of 120 events as 90 compressions plus 30 inflations."}, "nn-oxygen": {"c": "Start resuscitation in air at term; 21-30% under 35 weeks", "s": "ANZCOR Guideline 13.4 for term and near-term newborns: \"air should be used initially\". ANZCOR Guideline 13.8 for preterm newborns UNDER 35 WEEKS: \"suggests commencing resuscitation either using room air or blended air and oxygen up to an oxygen concentration of 30%\" (weak recommendation, very low certainty evidence)", "u": "https://www.anzcor.org/home/neonatal-resuscitation/guideline-13-8-the-resuscitation-of-the-newborn-in-special-circumstances", "d": "26 October 2026", "r": "October 2027", "v": "corrected", "n": "The page previously read \"under 32 weeks\". The 21-30% range is correct; the gestational threshold was three weeks too low. ANZCOR sets this recommendation at under 35 weeks. Most likely conflated with the polyethylene wrap threshold, which genuinely is 32 weeks and sits in an adjacent box. Corrected 26 October 2026."}, "nn-cord": {"c": "Delayed cord clamping for at least 60 seconds if vigorous", "s": "ANZCOR 2021 newborn guidelines, key recommendations: for term and late preterm infants at 34 weeks or more who are vigorous or do not need immediate resuscitation, delay cord clamping for at least 60 seconds. For infants born under 34 weeks not needing immediate resuscitation, delay for at least 30 seconds", "u": "https://www.neoresus.org.au/wp-content/uploads/2021/10/ANZCOR-2021-Newborn-Guidelines-Key-recommendations.pdf", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": "Correct as written but incomplete: the map does not carry the separate 30-second recommendation for infants under 34 weeks. Flagged for the author rather than changed, since adding it alters the line's meaning."}, "nn-sats": {"c": "Preductal saturation targets: 1 min 60-70%, 2 min 65-85%, 3 min 70-90%, 4 min 75-90%, 5 min 80-90%, 10 min 85-90%", "s": "ANZCOR Guideline 13.4, Recommendation 20, target range for oxygen saturations during newborn resuscitation. All six pairs match the published table exactly", "u": "https://www.resus.org.nz/assets/Uploads/Neonatal-Resuscitation-All-Guidelines.pdf", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "nn-roomtemp": {"c": "Ambient room temperature 26 degrees C or more for the preterm newborn, with hat, warmer and polyethylene wrap under 32 weeks", "s": "ANZCOR Guideline 13.8: place the newborn immediately after birth, without drying, in a polyethylene bag or under a polyethylene sheet, and establish \"an ambient temperature of at least 26 degrees C\". The ANZCOR 2021 key recommendations give the same figure among the additional measures for preterm infants", "u": "https://www.anzcor.org/home/neonatal-resuscitation/guideline-13-8-the-resuscitation-of-the-newborn-in-special-circumstances", "d": "26 October 2026", "r": "October 2027", "v": "corrected", "n": "The page previously read \"room at 23-25 degrees C\" in the same sentence as the preterm polyethylene wrap. 23-25 degrees C is a common general delivery-room figure but is below the ANZCOR recommendation for the preterm newborn, which is at least 26. The sentence is explicitly about the preterm baby, so as written it was too cold for the infant it described. Corrected 26 October 2026."}, "nn-ett-size": {"c": "Endotracheal tube internal diameter: 2.5 under 1 kg, 3.0 at 1-2 kg, 3.5 at 2-3 kg, 3.5-4.0 above", "s": "ANZCOR Guideline 13.5, weight-based tube sizes: 2.5 mm under 1 kg, 3.0 mm for 1 to 2 kg, 3.5 mm for 2 to 3 kg, and 3.5 or 4.0 mm above 3 kg. The guideline also gives a gestation rule, internal diameter in mm equal to gestational age in weeks divided by 10", "u": "https://www.anzcor.org/home/neonatal-resuscitation/guideline-13-5-tracheal-intubation-and-ventilation-of-the-newborn", "d": "26 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "nn-ett-depth": {"c": "Depth at the lip in centimetres is approximately weight in kg plus 6, and overestimates under 1 kg", "s": "MSD/Merck Manual Professional, Endotracheal intubation in neonates. Re-checked 11 November 2026 against the weight-banded depth table: the weight-plus-six rule runs about half a centimetre deep across the whole range, not only below 1 kg — 0.5 kg gives 5.5 cm against 6.5 by the rule, 1 kg gives 6.5 against 7, 3 kg gives 8.5 against 9. The caveat on the page is right in direction and too narrow in scope.", "u": "https://www.anzcor.org/home/neonatal-resuscitation/guideline-13-5-tracheal-intubation-and-ventilation-of-the-newborn", "d": "11 November 2026", "r": "November 2027", "v": "corrected", "n": "The formula is in the guideline, so the page was not wrong, but it was unsafe without the caveat: at 500 g the formula is a full centimetre too deep, which in a newborn with a short trachea is the right main bronchus. The page now carries the caution. The underlying guideline table should be the source of truth in the smallest infants."}, "nn-uvc": {"c": "Emergency umbilical venous catheter inserted 4-5 cm beyond the abdominal wall, until blood draws freely", "s": "No ANZCOR source. Guideline 13.7 does not give an insertion depth, nor does 13.8, nor the NeoResus circulation material. The nearest Australian guideline located is Royal Hospital for Women Newborn Care Centre, Umbilical Catheterisation (August 2018), which gives \"emergency UVC access 5 cm plus cord length\" - a different figure measured from a different landmark", "u": "https://www.seslhd.health.nsw.gov.au/sites/default/files/groups/Royal_Hospital_for_Women/Neonatal/Medical/nccumbilicalcath2018.pdf", "d": "26 October 2026", "r": "October 2027", "v": "flagged", "n": "The depth itself is conventional and widely taught, but it has no guideline source and the published Australian figure is measured from the cut cord rather than the abdominal wall. The page now names the landmark, which was the actual ambiguity, and the real safeguard remains the instruction to stop when blood draws freely. Worth revisiting if ANZCOR ever specifies a depth."}, "cm-ici": {"c": "Immune checkpoint inhibitor myocarditis: incidence about 1%, median onset 27-34 days, mortality 27-50%, troponin raised in 94%, methylprednisolone 500-1000 mg daily for 3-5 days, up to half steroid-refractory", "s": "Mauriello A et al, Immune Checkpoint Inhibitor Myocarditis, Journal of Clinical Medicine 2026;15:814, which gives incidence 0.3-1.4%, median onset 27-34 days (IQR 18-75) with most within the first 65 days, mortality 27-50%, troponin elevation in 94%, and methylprednisolone 500-1000 mg/day for 3-5 days", "u": "https://www.mdpi.com/2077-0383/15/3/814", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "cm-etoh-share": {"c": "Alcohol accounts for 23-47% of cases labelled idiopathic dilated cardiomyopathy in European series", "s": "Guzzo-Merello G et al, Alcoholic cardiomyopathy, World Journal of Cardiology 2014;6:771-781", "u": "https://www.wjgnet.com/1949-8462/full/v6/i8/771.htm", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "cm-etoh-threshold": {"c": "The diagnostic threshold of more than 80 g of alcohol a day for at least five years is arbitrary, by the authors' own description", "s": "Guzzo-Merello G et al, World Journal of Cardiology 2014;6:771-781, which states the threshold is \"arbitrary and not based on robust experimental or epidemiological data\"", "u": "https://www.wjgnet.com/1949-8462/full/v6/i8/771.htm", "d": "28 October 2026", "r": null, "v": "confirmed", "n": "Quoted rather than paraphrased on the page, because the point of the claim is that the number is soft. Clinicians use it as if it were a cut-off."}, "cm-etoh-recovery": {"c": "After withdrawal, ejection fraction improved from 30 plus or minus 12% to 43 plus or minus 16% at nine months", "s": "Guzzo-Merello G et al, World Journal of Cardiology 2014;6:771-781, reporting 30+/-12% to 43+/-16% at 9+/-4 months", "u": "https://www.wjgnet.com/1949-8462/full/v6/i8/771.htm", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "cm-rate-camera": {"c": "CAMERA-MRI: in persistent AF with ejection fraction 45% or less, ablation raised ejection fraction by 18% absolute against 4.4% for rate control, and normalised it in 58% against 9%", "s": "CAMERA-MRI (Prabhu S et al), presented ESC 2017 and published in the Journal of the American College of Cardiology 2017. Figures taken from the American College of Cardiology's own trial summary: 68 randomised of 301 screened, entry LVEF 45% or less with persistent AF and idiopathic cardiomyopathy, LVEF +18+/-13% versus +4.4+/-13% (p<0.0001), normalisation to 50% or more in 58% versus 9% (p=0.0002)", "u": "https://www.acc.org/latest-in-cardiology/journal-scans/2017/08/27/05/39/catheter-ablation-versus-medical-rate-control-in-af-esc-2017", "d": "28 October 2026", "r": "October 2027", "v": "flagged", "n": "Flagged, not confirmed: the numbers come from the publishing society's summary of the trial, not from the primary paper, because the JACC full text would not load. The society is about as good as a secondary source gets and the figures are internally consistent, but the primary should be read at next review and the volume and page numbers added."}, "cm-meth-rise": {"c": "Methamphetamine-associated cardiomyopathy rose from 1.8% of new cardiomyopathy diagnoses in 2009 to 5.6% in 2014, and an Australian autopsy series of methamphetamine-related deaths found cardiomyopathy in 5.5%", "s": "Clinical Characteristics and Management of Methamphetamine-Associated Cardiomyopathy: State-of-the-Art Review, Journal of the American Heart Association 2020;9:e016704", "u": "https://www.ahajournals.org/doi/10.1161/JAHA.120.016704", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "The 1.8% to 5.6% figures are from one region of southern California, which the page says. They are a trend in one place, not an Australian incidence. The Australian figure in the same review is the autopsy one."}, "cm-meth-ef": {"c": "Methamphetamine cardiomyopathy presents with mean ejection fraction 20 plus or minus 11%, and about a third recover left ventricular function by six weeks with abstinence", "s": "Journal of the American Heart Association 2020;9:e016704, reporting mean LVEF 20+/-11% in a 19-patient series, of whom 6 (32%) recovered by 6 weeks", "u": "https://www.ahajournals.org/doi/10.1161/JAHA.120.016704", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "Nineteen patients, so the recovery proportion is six people. The page says \"about a third\", which is faithful, but the denominator is small and a reader should know it."}, "cm-cloz": {"c": "Clozapine myocarditis monitoring: weekly troponin and CRP for the first four weeks; troponin above twice the upper limit of normal, or CRP above 100 mg/L, means stop the drug and arrange an echocardiogram", "s": "Hunter New England, Clozapine-induced Myocarditis Monitoring Guideline, which specifies high-sensitivity troponin I or T and CRP weekly for weeks 1 to 4 then six-monthly, continuation permitted below twice the upper limit of normal with CRP under 100 mg/L, and cessation plus echocardiography above either threshold", "u": "https://hnc.org.au/wp-content/uploads/2021/12/Draft-Clozapine-induced-Myocarditis-Monitoring-Guideline-2021.pdf", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "A local health district guideline, which is the right kind of source for a monitoring protocol but is local. The document located is marked draft and dated 2021; the thresholds match the protocol in general Australian use. No incidence figure is asserted on the page because this guideline gives none."}, "cm-myo-fulminant": {"c": "Fulminant myocarditis is 3-9% of acute myocarditis; within fulminant cases sustained ventricular arrhythmia occurs in about 47% and about 26% present with sudden cardiac death; about 75% of unselected cases are uncomplicated", "s": "2025 ESC Guidelines for the management of myocarditis and pericarditis, European Heart Journal 2025;46(40):3952-4041, doi:10.1093/eurheartj/ehaf192", "u": "https://academic.oup.com/eurheartj/article/46/40/3952/8234483", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "cm-myo-recovery": {"c": "In biopsy-diagnosed acute myocarditis, up to 50% recover spontaneously, up to 25% have persistent stable dysfunction, and 10-25% progress to end-stage disease, transplantation or death", "s": "2025 ESC Guidelines for the management of myocarditis and pericarditis, European Heart Journal 2025;46(40):3952-4041", "u": "https://academic.oup.com/eurheartj/article/46/40/3952/8234483", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "Biopsy-diagnosed, therefore a selected and sicker population than all-comers with myocarditis. The page states the condition."}, "cm-ppcm": {"c": "Peripartum cardiomyopathy: incidence about 1 in 100 in Nigeria to 1 in 10,000 in Denmark; mortality 8.0% at six months and 9.8% at twelve; recurrence in a subsequent pregnancy 30-50%", "s": "Farroni S et al, Peripartum cardiomyopathy, Vessel Plus 2025;9:2, giving Nigeria 1:100, Haiti 1:299, South Africa 1:1000, United States 1:1316 (2011) and Denmark 1:10,000; mortality 8.0% at 6 months and 9.8% at 12 months; recurrence 30-50%; and the ESC position against subsequent pregnancy where LVEF has not returned to baseline", "u": "https://www.oaepublish.com/articles/2574-1209.2024.69", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "No Australian incidence figure was located. The page places Australia between the quoted extremes without giving a number, which is as much as the source supports."}, "cm-sarcoid": {"c": "Cardiac involvement is found in 20-30% of systemic sarcoidosis but is symptomatic in only about 5%; atrioventricular block occurs in 35-50% of cardiac sarcoidosis; suspect it in anyone under sixty with unexplained heart block", "s": "Merck Manual Professional Edition, Cardiac Sarcoidosis", "u": "https://www.merckmanuals.com/professional/cardiovascular-disorders/arrhythmogenic-cardiac-disorders/cardiac-sarcoidosis", "d": "28 October 2026", "r": "October 2027", "v": "flagged", "n": "Flagged on two counts. It is a tertiary source, and the primary - the Heart Rhythm Society expert consensus statement on cardiac sarcoidosis - was not read. And the source contradicts itself: the body text says 20 to 30% and its own Key Points say 20 to 35%. The page uses the lower, body-text figure. The actionable part, suspicion under sixty with unexplained block, is the part least likely to move. Separately, the often-quoted figure that about a quarter of unexplained atrioventricular block in 18 to 55 year olds is sarcoid or giant cell myocarditis (Kandolin et al, 2011) was deliberately left off the page because the paper could not be reached to check it."}, "cm-inherited": {"c": "Up to 20-30% of dilated cardiomyopathy is monogenic", "s": "ESC consensus material on the genetics of dilated cardiomyopathy and family screening (PMC12614981)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12614981/", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "cm-family": {"c": "Screening first-degree relatives finds cardiomyopathy in 9-22% at the baseline visit, and 11% of pathogenic or likely-pathogenic variant carriers with a normal baseline developed dilated cardiomyopathy over a median three years", "s": "ESC consensus material on the genetics of dilated cardiomyopathy and family screening (PMC12614981), which also gives about 2% per person-year on serial screening, up to 8.9% in variant carriers, and recommends baseline ECG and cardiac imaging for every first-degree relative", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12614981/", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "cm-iron": {"c": "Cardiac T2* below 10 ms is severe myocardial iron loading, and in transfusion-dependent thalassaemia the one-year risk of heart failure was 47% below 6 ms against 0.2% above 10 ms", "s": "Agrawal A et al, A Contemporary Review of Clinical Manifestations, Evaluation, and Management of Cardiac Complications of Iron Overload, Hearts 2025;6(3):17, doi:10.3390/hearts6030017, citing 652 patients with thalassaemia major: one-year heart failure risk 47% at T2* under 6 ms, 21% at 6-10 ms, 0.2% above 10 ms", "u": "https://www.mdpi.com/2673-3846/6/3/17", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "cm-tts": {"c": "Takotsubo syndrome is about 90% women, mean age 67-70, about 80% over fifty; recurrence 1.8% per patient-year; in-hospital mortality comparable to STEMI", "s": "International Expert Consensus Document on Takotsubo Syndrome, European Heart Journal 2018;39:2032", "u": "https://academic.oup.com/eurheartj/article/39/22/2032/5025411", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "Carried on this page to make the opposite point from the usual one: the word STRESS completes the mnemonic but the disease belongs to an older patient. The secondary, catecholamine-driven form described alongside it is a mechanism rather than a counted entity and carries no number."}, "ef3-structure": {"c": "The CICM First Part written examination is two papers, each carrying 50 multiple choice questions and 10 short answer questions", "s": "CICM T-17 Notes to Candidates for the First Part Examination (2026-2), which describes '2 x 2.5 hour written papers' with 50 MCQs and 10 SAQs each. Confirmed independently on the College's First Part Examination page, which states the same structure", "u": "https://cicm.org.au/common/Uploaded%20files/Assets/Training%20and%20Education/Trainee%20Documents/T-17%202026-2.pdf", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "ef3-schedule": {"c": "The published schedule for each paper is 165 minutes: 5 minutes labelling, 10 minutes reading with no writing, 50 minutes for the MCQs and 100 minutes for the SAQs", "s": "CICM T-17 Notes to Candidates (2026-2), which gives the segment timings and states that this allows '1 minute per MCQ and 10 minutes for each SAQ'", "u": "https://cicm.org.au/common/Uploaded%20files/Assets/Training%20and%20Education/Trainee%20Documents/T-17%202026-2.pdf", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "Worth stating carefully, because the paper is described everywhere as a 2.5 hour paper, which is 150 minutes - that is the question time. The labelling and reading segments sit outside it, so the candidate is in the room for 165 minutes. Both figures are correct and they are not the same thing."}, "ef3-format": {"c": "Each MCQ offers four options, A to D, and asks for one answer; answers are recorded on the prescribed sheet in 2B pencil only; non-programmable calculators are permitted and programmable ones are not", "s": "CICM T-17 Notes to Candidates (2026-2), which instructs candidates to 'Select ONE answer from the four options', requires a '2B pencil ONLY' for the MCQ answer sheet, and permits non-programmable calculators. The College's First Part Examination page separately lists permitted and prohibited items", "u": "https://cicm.org.au/common/Uploaded%20files/Assets/Training%20and%20Education/Trainee%20Documents/T-17%202026-2.pdf", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": ""}, "ef3-marks": {"c": "The College's table values the MCQs at 100 marks and the SAQs at 400 marks", "s": "CICM T-17 Notes to Candidates (2026-2), marks table. The orals are listed separately at 160 marks across 8 vivas", "u": "https://cicm.org.au/common/Uploaded%20files/Assets/Training%20and%20Education/Trainee%20Documents/T-17%202026-2.pdf", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "The page draws the inference that MCQs are a fifth of the written marks and about a third of the working time. The 100 and 400 are the College's figures; the ratio is arithmetic on them. T-17 does not state a per-question MCQ mark."}, "ef3-angoff": {"c": "A candidate must reach or exceed the Angoff pass mark on the MCQ component and on the SAQ component separately, with no aggregate between them", "s": "CICM First Part Examination page, which states that to progress to the vivas candidates must reach the Angoff score or greater on the SAQ section and on the MCQs, listing them as separate criteria and describing no combined score. T-17 states the same", "u": "https://www.cicm.org.au/Web/Training-and-Education/TrainingPages/General-and-Paediatric-ICT-Program-Pages/Assessments-and-Examinations/First-Part-Examination.aspx", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "This is the load-bearing fact of the whole page: it is what makes a component worth only a fifth of the marks impossible to ignore. Both College documents say it independently, which is why it is recorded as confirmed rather than as an inference."}, "ef3-passrate": {"c": "In the 2023.1 sitting the MCQ pass rate was 86% overall, 92% on Paper 1 and 82% on Paper 2; 76 candidates sat the written and 37 were invited to the orals", "s": "Report of the Intensive Care First Part Examination, March/May 2023 (2023.1), published by CICM", "u": "https://cicm.org.au/common/Uploaded%20files/Assets/Training%20and%20Education/General%20and%20Paediatric%20Intensive%20Care/Assessments%20and%20Examination/First%20Part%20Examination/2020-2024/FINAL_First-Part-Exam-Report-2023-1.pdf", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "One sitting, and sittings vary - the page says 2023.1 by name rather than presenting it as a standing figure. The report gives these percentages under its MCQ heading without defining 'pass rate' precisely; read in context it is the proportion of candidates reaching the standard on that paper's MCQs. The 76 and 37 are from the same report and are the figures that carry the argument, since they show the written component halving the cohort while the MCQ pass rate stayed high."}, "ef3-nopastmcq": {"c": "The College publishes past short answer questions but does not publish past multiple choice questions", "s": "CICM First Part Examination page, whose past written papers are listed as 2026.2 and 2025.2 in morning (SAQs 1-10) and afternoon (SAQs 11-20) versions only. The published examination reports give MCQ pass rates and no MCQ items", "u": "https://www.cicm.org.au/Web/Training-and-Education/TrainingPages/General-and-Paediatric-ICT-Program-Pages/Assessments-and-Examinations/First-Part-Examination.aspx", "d": "28 October 2026", "r": "October 2027", "v": "confirmed", "n": "An absence rather than a statement, so it is evidenced by what the College publishes rather than by a sentence saying so. Checked against the current page listing and against the 2023.1 report. If the College ever releases MCQs this claim fails quietly, which is why it carries a 12-month interval rather than 'never'."}, "ef3-blank": {"c": "Candidates are advised to attempt every question because each is scored equally and unanswered questions forfeit marks; no negative marking is published", "s": "Report of the Intensive Care First Part Examination, March/May 2023, general advice to candidates: attempt all questions, since each is scored equally and unanswered questions forfeit marks, and apportion time accordingly", "u": "https://cicm.org.au/common/Uploaded%20files/Assets/Training%20and%20Education/General%20and%20Paediatric%20Intensive%20Care/Assessments%20and%20Examination/First%20Part%20Examination/2020-2024/FINAL_First-Part-Exam-Report-2023-1.pdf", "d": "28 October 2026", "r": "October 2027", "v": "flagged", "n": "Flagged rather than confirmed on the negative-marking half. The College's advice to attempt everything is quoted directly and is unambiguous. That no negative marking exists is an inference from its absence in T-17, in the First Part Examination page and in the examination reports - no document says so in terms. The practical advice on the page (never leave a blank) is safe under either scheme, since the College's own instruction is to attempt everything. Worth asking the College directly, or checking a future T-17 for an explicit statement."}, "ef3-firstinstinct": {"c": "Changing an answer on a multiple choice paper more often helps than harms: of 3,291 changed answers 51% went wrong to right and 25% right to wrong, and of students who changed at least one answer 54% were helped and 19% hurt", "s": "Kruger J, Wirtz D, Miller DT. Counterfactual thinking and the first instinct fallacy. Journal of Personality and Social Psychology 2005;88(5):725-735. Study 1, 1,561 University of Illinois students. The paper also cites a review of 33 studies finding test takers were not harmed on average by changing answers", "u": "https://people.wku.edu/steven.wininger/Kruger%20First%20Instinct%20Myth.pdf", "d": "28 October 2026", "r": null, "v": "confirmed", "n": "Interval set to never: this is a published result from a fixed dataset, not a figure that republishes. Note what it does and does not license. It refutes the folk rule that a first instinct should be preserved; it does not say that changing answers is good in itself, and the undergraduate setting is not a postgraduate specialist examination. The page states it as a reason to change on a stated reason rather than on a feeling, which is the defensible reading."}, "pan-revise-bleed": {"c": "REVISE: in 4,900 invasively ventilated adults, clinically important upper gastrointestinal bleeding occurred in 1.0% on pantoprazole 40 mg daily against 3.5% on placebo; hazard ratio 0.30 (95% CI 0.19-0.47); absolute difference 2.5 percentage points (1.6-3.3); number needed to treat 40", "s": "Cook D and colleagues (REVISE Investigators), Stress Ulcer Prophylaxis during Invasive Mechanical Ventilation, New England Journal of Medicine 2024;391(1):9-20, as recorded in the Critical Care Reviews foundational trial entry, which gives the event counts (25/2,385 against 84/2,377). The Bottom Line's independent summary gives the same percentages and states the number needed to treat as 40", "u": "https://criticalcarereviews.com/foundational-trials/revise", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-revise-mortality": {"c": "REVISE: 90-day all-cause mortality 29.1% on pantoprazole against 30.9% on placebo; hazard ratio 0.94 (95% CI 0.85-1.04), adjusted for baseline APACHE II", "s": "Cook D and colleagues (REVISE), New England Journal of Medicine 2024;391:9, via the Critical Care Reviews trial record (696/2,390 against 734/2,379). The Bottom Line reports the same, and adds ICU mortality 20.3% against 21.5% and hospital mortality 26.3% against 28.4%, neither significant", "u": "https://criticalcarereviews.com/foundational-trials/revise", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-severity": {"c": "Mortality by illness severity: in REVISE the hazard ratio was 0.85 (95% CI 0.74-0.98) below an APACHE II of 25 and 1.04 (0.89-1.20) at or above it; in SUP-ICU the relative risks were 0.92 and 1.13. Neither interaction reached significance", "s": "Granholm A and colleagues, Preventing stress ulcer bleeding, Intensive Care Medicine 2024, which sets both trials' subgroup estimates side by side and gives the interaction p values as 0.05 for SUP-ICU and 0.27 for REVISE. The REVISE subgroup hazard ratios match the Critical Care Reviews trial record independently", "u": "https://link.springer.com/article/10.1007/s00134-024-07674-3", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "Recorded carefully because the secondary summaries disagree about one number: The Bottom Line gives REVISE's interaction p as 0.12, while Critical Care Reviews and the Intensive Care Medicine review both give 0.27. The page therefore states only that neither interaction reached significance, which all three sources agree on, and quotes no interaction p value."}, "pan-sup-dose": {"c": "For stress ulcer prophylaxis, low-dose is recommended over high-dose therapy, low dose being defined as up to 40 mg daily of pantoprazole", "s": "Society of Critical Care Medicine and American Society of Health-System Pharmacists, Guideline for the Prevention of Stress-Related Gastrointestinal Bleeding in Critically Ill Adults, Critical Care Medicine 2024;52(8), which defines low dose as up to 40 mg daily for esomeprazole, omeprazole or pantoprazole and up to 30 mg for lansoprazole", "u": "https://www.sccm.org/clinical-resources/guidelines/guidelines/sccm-ashp-guideline-prevention-of-ugib", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-sup-risk": {"c": "The risk factors identified for clinically important upper gastrointestinal bleeding are coagulopathy, shock and chronic liver disease; the guideline found no firm evidence that mechanical ventilation alone is one", "s": "SCCM and ASHP guideline, Critical Care Medicine 2024;52(8) - conditional recommendation, low to moderate certainty", "u": "https://www.sccm.org/clinical-resources/guidelines/guidelines/sccm-ashp-guideline-prevention-of-ugib", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The page sets this against REVISE, which enrolled by ventilation and found a benefit, and says so rather than reconciling them. Both statements are accurately reported."}, "pan-sup-route": {"c": "The prophylactic dose is 40 mg once daily and may be given by either the enteral or the intravenous route", "s": "SCCM and ASHP guideline, Critical Care Medicine 2024;52(8), which suggests enteral or intravenous administration (conditional, low certainty), together with its low-dose definition of up to 40 mg daily", "u": "https://www.sccm.org/clinical-resources/guidelines/guidelines/sccm-ashp-guideline-prevention-of-ugib", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-stopping": {"c": "Prophylaxis should be stopped once the risk factor is no longer present, and stopped before the patient is transferred out of the intensive care unit", "s": "SCCM and ASHP guideline, Critical Care Medicine 2024;52(8) - good practice statements, which give the reason as prevention of inappropriate continued prescribing", "u": "https://www.sccm.org/clinical-resources/guidelines/guidelines/sccm-ashp-guideline-prevention-of-ugib", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-meta": {"c": "A 2026 meta-analysis of nine randomised trials in 8,388 invasively ventilated adults: clinically important upper gastrointestinal bleeding odds ratio 0.36 (95% CI 0.19-0.69); all-cause mortality 0.98 (0.89-1.07); ventilator-associated pneumonia 0.99 (0.87-1.12); Clostridioides difficile infection 1.63 (0.97-2.73)", "s": "Hu and colleagues, Prophylactic Proton Pump Inhibitors in Critically Ill Patients Undergoing Invasive Ventilation: A Systematic Review and Meta-Analysis of Randomized Trials, Critical Care Research and Practice 2026", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13238534/", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "Odds ratios, not risk ratios - the page says odds ratio. The authors note the C. difficile estimate is imprecise because event rates are low, and the page says the same."}, "pan-deprescribe": {"c": "In five Western Australian intensive care units, 184 of 531 consecutive adults were started on a proton pump inhibitor for stress ulcer prophylaxis; 90 of them (48.9%) were still taking it at hospital discharge, and 9 of those 90 had a documented indication", "s": "Tan B, Norman R, Litton E, Heath C, Hawkins D, Krishnamurthy R, Sonawane R, Anstey M. Incidence and cost of stress ulcer prophylaxis after discharge from the intensive care unit: a retrospective study. Critical Care and Resuscitation 2016;18(4):270-274. Patients admitted September 2013 to January 2015", "u": "https://espace.curtin.edu.au/handle/20.500.11937/7940", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-deprescribe-cost": {"c": "The same study estimated an additional $180.20 per intensive care admission and a direct cost of about $250,800 a year to the Western Australian health system from unnecessary proton pump inhibitors continued at discharge", "s": "Tan B and colleagues, Critical Care and Resuscitation 2016;18(4):270-274, assuming a ten-year life expectancy after discharge and counting only drug cost, not the cost of managing adverse effects", "u": "https://espace.curtin.edu.au/handle/20.500.11937/7940", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "2016 Australian dollars, and the page treats the figure as an order of magnitude rather than a current price."}, "pan-ugib-dose": {"c": "After successful endoscopic haemostasis of a bleeding ulcer, high-dose proton pump inhibitor therapy for three days: 80 mg bolus then 8 mg/h by infusion, or 80 mg bolus then 40 mg two to four times daily", "s": "Laine L, Barkun AN, Saltzman JR, Martel M, Leontiadis GI. ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding. American Journal of Gastroenterology 2021;116(5):899-917, statement 13 and its discussion", "u": "https://docs.bvsalud.org/biblioref/2021/07/1281327/acg_clinical_guideline__upper_gastrointestinal_and14.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The continuous regimen is in the formal statement; the intermittent regimen appears in the discussion, and the authors say the optimal intermittent dosing is uncertain. The page gives both and says to choose on cost and ease, which is the guideline's own instruction."}, "pan-ugib-duration": {"c": "The recommended duration of high-dose therapy after endoscopic haemostasis is three days (72 hours) - a strong recommendation on moderate to high quality evidence", "s": "Laine and colleagues, ACG Clinical Guideline, American Journal of Gastroenterology 2021;116:899, statement 13", "u": "https://docs.bvsalud.org/biblioref/2021/07/1281327/acg_clinical_guideline__upper_gastrointestinal_and14.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-ugib-effect": {"c": "High-dose proton pump inhibitor after endoscopic haemostasis, against placebo or no treatment: further bleeding relative risk 0.43 (95% CI 0.33-0.56), mortality 0.41 (0.22-0.79)", "s": "Laine and colleagues, ACG Clinical Guideline, American Journal of Gastroenterology 2021;116:899, evidence summary for statement 13", "u": "https://docs.bvsalud.org/biblioref/2021/07/1281327/acg_clinical_guideline__upper_gastrointestinal_and14.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "A widely circulated secondary summary of this guideline quotes absolute reductions of 3% for mortality and 10% for further bleeding. The guideline text itself reports only these relative effects for that comparison, so the page uses the relative figures."}, "pan-continuous": {"c": "In the guideline's own comparison of continuous bolus-and-infusion against less intensive regimens, the further bleeding risk difference was 1% (95% CI -2% to 4%), trending towards more bleeding with the bolus-and-infusion", "s": "Laine and colleagues, ACG Clinical Guideline, American Journal of Gastroenterology 2021;116:899", "u": "https://docs.bvsalud.org/biblioref/2021/07/1281327/acg_clinical_guideline__upper_gastrointestinal_and14.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-twice-daily": {"c": "In high-risk ulcer bleeding, twice-daily oral proton pump inhibitor from days 4 to 14 after index endoscopy: further bleeding at 28 days 10/93 (10.8%) against 27/94 (28.7%) for once daily, difference -18% (95% CI -29% to -7%) - a conditional recommendation on low quality evidence", "s": "Laine and colleagues, ACG Clinical Guideline, American Journal of Gastroenterology 2021;116:899, statement 14, which rests on a single randomised trial (Lau and colleagues)", "u": "https://docs.bvsalud.org/biblioref/2021/07/1281327/acg_clinical_guideline__upper_gastrointestinal_and14.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-preendoscopy": {"c": "The American College of Gastroenterology reached no recommendation for or against proton pump inhibitor therapy before endoscopy", "s": "Laine and colleagues, ACG Clinical Guideline, American Journal of Gastroenterology 2021;116:899: 'We could not reach a recommendation for or against pre-endoscopic PPI therapy for patients with UGIB.' No strength or quality rating is assigned", "u": "https://docs.bvsalud.org/biblioref/2021/07/1281327/acg_clinical_guideline__upper_gastrointestinal_and14.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-preendoscopy-trial": {"c": "In the randomised trial underlying that non-recommendation, further bleeding was 3.5% against 2.5% (difference 1%, 95% CI -2% to 4%) and mortality 2.5% against 2.2% (difference 0%, -2% to 3%)", "s": "Laine and colleagues, ACG Clinical Guideline, American Journal of Gastroenterology 2021;116:899, reporting pre-endoscopy omeprazole against placebo (Lau and colleagues)", "u": "https://docs.bvsalud.org/biblioref/2021/07/1281327/acg_clinical_guideline__upper_gastrointestinal_and14.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The trial used omeprazole, not pantoprazole. The page presents it as the evidence behind the guideline position on the class, which is how the guideline uses it."}, "pan-varices": {"c": "Proton pump inhibitors after endoscopic band ligation of oesophageal varices in cirrhosis: four randomised trials, 445 patients - bleeding within eight weeks relative risk 0.71 (95% CI 0.39-1.30), mortality 0.75 (0.23-2.53)", "s": "Pedral Diniz Leite GA and colleagues, STOP PPIS - No reduction in bleeding or mortality after endoscopic banding ligation for esophageal varices in cirrhotics: a systematic review and meta-analysis of randomized controlled trials, Annals of Hepatology 2025;30(Suppl 2):102024", "u": "https://www.elsevier.es/en-revista-annals-hepatology-16-articulo-stop-ppis-no-reduction-S1665268125002492", "d": "3 November 2026", "r": "November 2027", "v": "flagged", "n": "FLAGGED because this is a conference abstract, not a full paper: the methods and the trial-level data are not available to check, and three of the four trials contributed to the mortality estimate. The page says so, says the confidence intervals are wide, and says explicitly that this is not proof of no effect. It is used to support a statement about priorities - vasoactive drug, antibiotics and endoscopy first - not a statement that proton pump inhibitors are useless here."}, "pan-pi-indications": {"c": "The Australian Product Information for the injection registers it for duodenal ulcer, gastric ulcer, reflux oesophagitis, gastrointestinal lesions refractory to H2 blockers and Zollinger-Ellison syndrome, at 40 mg a day. Stress ulcer prophylaxis is not a registered indication, and no infusion regimen is described", "s": "Somac Injection Australian Product Information, sections on indications and dose and administration, accessed 3 November 2026", "u": "https://medsinfo.com.au/api/documents/Somac_Injection_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "This claim is partly about an absence, which is why it is recorded: both of the uses the page describes most fully - prophylaxis, and 8 mg/h after a bleeding ulcer - are outside the Australian registration, and the page says so twice."}, "pan-pi-dose": {"c": "Registered Australian intravenous dose: 40 mg a day for duodenal and gastric ulcer, refractory lesions and Zollinger-Ellison syndrome; 20 to 40 mg a day for reflux oesophagitis; usual doses in the elderly and in renal impairment; switch to oral therapy as soon as practicable", "s": "Somac Injection Australian Product Information, dose and administration, accessed 3 November 2026", "u": "https://medsinfo.com.au/api/documents/Somac_Injection_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-pi-recon": {"c": "Reconstitute with 10 mL of 0.9% sodium chloride; the solution may be given as it is or mixed with 100 mL of 0.9% sodium chloride or 100 mL of 5% or 10% glucose; infuse over 2 to 15 minutes", "s": "Somac Injection Australian Product Information, accessed 3 November 2026", "u": "https://medsinfo.com.au/api/documents/Somac_Injection_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-pi-mixing": {"c": "The Product Information directs that it not be mixed with medicinal products other than the listed diluents", "s": "Somac Injection Australian Product Information, accessed 3 November 2026. The product also contains no antimicrobial preservative and is for single use", "u": "https://medsinfo.com.au/api/documents/Somac_Injection_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-pi-storage": {"c": "If storage after reconstitution is necessary, hold at 2 to 8 degrees Celsius for no more than 12 hours; discard any solution that is cloudy or has precipitated", "s": "Somac Injection Australian Product Information, accessed 3 November 2026", "u": "https://medsinfo.com.au/api/documents/Somac_Injection_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-pi-liver": {"c": "The Australian Product Information contraindicates pantoprazole in cirrhosis or severe liver disease, and directs a reduced initial dose in milder liver disease", "s": "Somac Australian Product Information, section 4.3 Contraindications - 'Known hypersensitivity to pantoprazole, substituted benzimidazoles or any other components of the formulation, or in cases of cirrhosis or severe liver disease' - and section 4.2, which states that with milder forms of liver disease the minimum effective dose has not been determined and the initial dose should be reduced. Read verbatim on 3 November 2026", "u": "https://medsinfo.com.au/api/documents/Somac_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "Recorded verbatim because the page makes a point of it and because ordinary Australian intensive care practice does the opposite. The label states no numerical reduced dose, so the page does not give one."}, "pan-hepatic": {"c": "In Child-Pugh A to C hepatic impairment the elimination half-life rises to 7 to 9 hours and exposure rises five- to sevenfold", "s": "Manufacturer clinical pharmacology data for pantoprazole, which states that these changes are no greater than those seen in CYP2C19 poor metabolisers and that minimal accumulation occurs with once-daily dosing", "u": "https://www.pfizermedical.com/protonix-iv/clinical-pharmacology", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-renal": {"c": "No dose adjustment is required in renal impairment, and no unchanged pantoprazole is excreted renally", "s": "Manufacturer clinical pharmacology data, which reports pharmacokinetic parameters in severe renal impairment similar to those in healthy subjects and no renal excretion of unchanged drug. The Australian Product Information separately gives the usual dose in renal impairment", "u": "https://www.pfizermedical.com/protonix-iv/clinical-pharmacology", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-duration": {"c": "Plasma half-life is about one hour, while the antisecretory effect persists for longer than 24 hours across doses from 20 to 120 mg", "s": "Manufacturer clinical pharmacology data, which reports a terminal elimination half-life of about 1 hour after biexponential decline and an antisecretory effect persisting longer than 24 hours, with onset within 15 to 30 minutes and near-complete suppression about 2 hours after 80 mg", "u": "https://www.pfizermedical.com/protonix-iv/clinical-pharmacology", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-pk": {"c": "Volume of distribution about 11 to 24 L, essentially extracellular; protein binding about 98%, mostly to albumin; clearance 7.6 to 14 L/h; hepatic metabolism by demethylation through CYP2C19 then sulfation with a minor CYP3A4 contribution; metabolites inactive; about 71% recovered in urine and 18% in faeces", "s": "Manufacturer clinical pharmacology data for the intravenous product", "u": "https://www.pfizermedical.com/protonix-iv/clinical-pharmacology", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The source gives the volume of distribution as 11 to 23.6 L; the page rounds to 11 to 24."}, "pan-poormetab": {"c": "In CYP2C19 poor metabolisers the elimination half-life is 3.5 to 10 hours, accumulation on once-daily dosing is 23% or less, and no dose adjustment is needed", "s": "Manufacturer clinical pharmacology data. The page's statement that poor metabolisers are a minority of Europeans and a larger minority of East Asian populations is consistent with the RxFiles summary, which gives 10 to 30% with reduced CYP2C19 activity and notes the higher prevalence in some Asian populations", "u": "https://www.pfizermedical.com/protonix-iv/clinical-pharmacology", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-bio": {"c": "Oral bioavailability is about 77%", "s": "United States prescribing information for pantoprazole sodium delayed-release tablets: 'an absolute bioavailability of approximately 77%'", "u": "https://medlibrary.org/lib/rx/meds/pantoprazole-sodium-8/page/4/", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "Taken from the American label because the Australian Product Information does not state an absolute bioavailability figure."}, "pan-food": {"c": "Food does not alter the peak concentration or the extent of absorption of oral pantoprazole, though it may delay absorption by up to two hours or longer; the label states it may be taken without regard to meals", "s": "United States prescribing information for pantoprazole delayed-release tablets: 'Administration ... with food may delay its absorption up to 2 hours or longer' but 'the Cmax and the extent of pantoprazole absorption (AUC) are not altered.' The Australian Product Information likewise gives no meal timing for the tablets and reports no food effect on absorption", "u": "https://medlibrary.org/lib/rx/meds/pantoprazole-sodium-8/page/4/", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "Recorded because secondary summaries often give a roughly 50% reduction in bioavailability with food as a class statement. The pantoprazole data do not show it, and the page makes the pre-meal argument on pharmacodynamic grounds instead."}, "pan-tablets": {"c": "The tablets are enteric coated and the Product Information states that they should be swallowed whole and not chewed or crushed", "s": "Somac Australian Product Information, accessed 3 November 2026", "u": "https://medsinfo.com.au/api/documents/Somac_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-granules": {"c": "The 40 mg granule preparation is intended for patients who have difficulty swallowing tablets and may be given through a nasogastric or gastric tube, or sprinkled in a small volume of juice or water and swallowed immediately", "s": "Somac Australian Product Information, which directs that the granules be taken on an empty stomach at least half an hour before a meal, and describes administration through a nasogastric or gastric tube. No granule formulation is listed for the 20 mg strength", "u": "https://medsinfo.com.au/api/documents/Somac_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-hpylori": {"c": "Helicobacter pylori eradication: 40 mg twice daily with antibiotics for 7 days, orally", "s": "Somac Australian Product Information, dose and administration, accessed 3 November 2026", "u": "https://medsinfo.com.au/api/documents/Somac_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-hypomag": {"c": "Hypomagnesaemia and hypocalcaemia are listed adverse effects of pantoprazole", "s": "Somac Injection Australian Product Information, adverse effects, where hypomagnesaemia and hypocalcaemia appear at a frequency of 'not known', alongside fracture of the wrist, hip and spine", "u": "https://medsinfo.com.au/api/documents/Somac_Injection_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-phlebitis": {"c": "Thrombophlebitis at the injection site is listed as a common adverse effect of the intravenous preparation", "s": "Somac Injection Australian Product Information, adverse effects, where it is the only effect listed as common", "u": "https://medsinfo.com.au/api/documents/Somac_Injection_PI?format=pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-cdiff": {"c": "REVISE: Clostridioides difficile infection in hospital, 28 patients (1.2%) on pantoprazole against 16 (0.7%) on placebo; hazard ratio 1.78 (95% CI 0.96-3.29), not significant", "s": "Cook D and colleagues (REVISE), New England Journal of Medicine 2024;391:9, via the Critical Care Reviews trial record, which notes the event counts are low and the estimate imprecise", "u": "https://criticalcarereviews.com/foundational-trials/revise", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-vap": {"c": "REVISE: ventilator-associated pneumonia in intensive care, 23.3% against 23.8%; hazard ratio 1.00 (95% CI 0.89-1.12)", "s": "Cook D and colleagues (REVISE), New England Journal of Medicine 2024;391:9, via the Critical Care Reviews trial record. Pneumonia was defined by a Clinical Pulmonary Infection Score of 6 or more", "u": "https://criticalcarereviews.com/foundational-trials/revise", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "pan-clopidogrel": {"c": "COGENT: omeprazole with clopidogrel reduced gastrointestinal bleeding, hazard ratio 0.13 (95% CI 0.03-0.56), with no excess of cardiovascular events, 0.99 (0.68-1.44). Pantoprazole is the proton pump inhibitor least likely to inhibit CYP2C19", "s": "RxFiles clinical question-and-answer on the clopidogrel-PPI interaction, summarising COGENT (Bhatt DL and colleagues, New England Journal of Medicine 2010;363:1909) and stating the consensus that pantoprazole does not inhibit CYP2C19 to any great extent, with rabeprazole a possible alternative and omeprazole the one to avoid", "u": "https://www.rxfiles.ca/RxFiles/uploads/documents/Clopidogrel-PPI-interaction-QandA.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "Two claims in one entry and they are not equally strong. The COGENT figures are randomised. The preference for pantoprazole is a pharmacological inference endorsed by consensus, not the result of a randomised comparison of one proton pump inhibitor against another in patients on clopidogrel - and the page says the interaction has never been convincingly demonstrated in patients."}, "pan-thc": {"c": "There is no evidence that proton pump inhibitors cause false-positive urine cannabinoid immunoassays: pantoprazole spiked at 10,000 ng/mL into negative urine did not produce a positive result, and none of 32 patient samples from people taking five different proton pump inhibitors met the positive cut-off", "s": "Academy of Diagnostics and Laboratory Medicine, Scientific Short, 'Up in Smoke: Uncovering a Lack of Evidence for Proton Pump Inhibitor Interference', reporting work on the EMIT II Plus Cannabinoid assay at a 20 ng/mL cut-off, together with LC-TOF-MS testing of 50 THC-positive urines that found no proton pump inhibitor or H2 antagonist. The claim's origin is traced to an early manufacturer's insert that cited no data", "u": "https://myadlm.org/science-and-research/scientific-shorts/2016/Up-in-Smoke", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The page states the negative finding, which is what the source supports. Absence of demonstrated cross-reactivity in one assay family is not proof for every assay, and the page's advice is correspondingly narrow: do not reach for this as an explanation."}, "pan-canaliculus": {"c": "The parietal cell secretory canaliculus sits at about pH 1, and the drug, a lipophilic weak base, concentrates there roughly a thousandfold", "s": "Reported consistently across secondary pharmacology sources, including LITFL's Pharm 101 entry on pantoprazole ('concentrated more than 1000-fold by Henderson-Hasselbalch trapping') and an independent pharmacology review giving a canalicular pH of about 1 and a concentration at the pump about 1000-fold higher than in blood", "u": "https://litfl.com/pharm-101-pantoprazole/", "d": "3 November 2026", "r": "November 2027", "v": "flagged", "n": "FLAGGED because the primary measurement has not been read. Two independent secondary sources agree, and the figure is used on the page as an order of magnitude in an explanation of mechanism, not as a quantity anyone would act on."}, "salon-erc2021": {"c": "ERC 2021 Adult Advanced Life Support, verbatim: 'Consider CPR for 60-90 min after administration of thrombolytic drugs.' No qualifier about selected patients appears in that sentence or in the thrombolysis recommendation beside it", "s": "European Resuscitation Council Guidelines 2021: Adult advanced life support, read in full on 3 November 2026. The thrombolysis recommendation in the same section reads 'Consider thrombolytic drug therapy when pulmonary embolus is the suspected or confirmed cause of cardiac arrest'", "u": "https://semicyuc.org/wp-content/uploads/2021/09/RCP-Guias-ERC-2021-05-SVA-adulto-Resuscitation-2021.pdf", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The word 'selected' does appear elsewhere in the 2021 chapter, in the recommendation on extracorporeal CPR. It does not appear in the pulmonary embolism recommendation, which is the claim the page makes."}, "salon-erc2025": {"c": "The 2025 wording is the 2021 sentence with seven words inserted in front of it: 'In select patients with suspected pulmonary embolism, consider CPR for 60-90 min after administration of thrombolytic drugs.' Nothing else in the sentence changed", "s": "2025 Adult Advanced Life Support guidelines as published by Resuscitation Council UK, carrying the ERC 2025 wording, read on 3 November 2026. The 2025 Special Circumstances chapter carries the same sentence, qualifier included", "u": "https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The page's whole argument rests on the two sentences being otherwise identical, so the builder asserts it mechanically: it checks that the 2025 string ends with the 2021 string, lower-cased at the join, and that the inserted span is seven words. An earlier draft of this page said four words. The check caught it."}, "salon-anzcor": {"c": "ANZCOR Guideline 11.10, approved July 2026, carries the duration as a Good Practice Statement with no selection qualifier: 'consider performing CPR for 60 to 90 min before termination of resuscitation attempts.' Its fibrinolysis recommendation for suspected pulmonary embolism is weak, on very low-certainty evidence", "s": "ANZCOR Guideline 11.10, Resuscitation in Special Circumstances, section 11.0, read on 3 November 2026; the page states it was approved in July 2026. The same section gives pulmonary embolism as the cause in about 2 to 7% of out-of-hospital arrests", "u": "https://www.anzcor.org/home/adult-advanced-life-support/guideline-11-10-resuscitation-in-special-circumstances", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "This is the load-bearing claim of the page, because it is what makes the argument local rather than academic: the European wording has moved and the Australian wording has not. Worth re-reading whenever ANZCOR reissues 11.10."}, "salon-er-cohort": {"c": "Er and colleagues, Cologne: 104 consecutive witnessed in-hospital arrests with confirmed (63) or strongly suspected (41) pulmonary embolism, all given rtPA during CPR; return of circulation in 40/104 (38.5%), survival to discharge 19/104 (18.3%)", "s": "Er F, Nia AM, Gassanov N and colleagues, Impact of rescue-thrombolysis during cardiopulmonary resuscitation in patients with pulmonary embolism, PLoS ONE 2009;4(12):e8323. Retrospective, University Hospital of Cologne, 2004 to 2008", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC2788709/", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "salon-er-timing": {"c": "In the same series, thrombolysis was given at 13.6 +/- 1.2 minutes after the start of CPR in patients who achieved return of circulation, against 24.6 +/- 0.8 minutes in those who did not (p<0.001); patients who survived to discharge had it at 11.0 +/- 1.3 minutes against 22.5 +/- 0.9 for everybody else (p<0.001)", "s": "Er and colleagues, PLoS ONE 2009;4(12):e8323. The Results section gives the no-ROSC figure as 24.7 +/- 0.8 in one place and 24.6 +/- 0.8 in another", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC2788709/", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The paper itself is internally inconsistent by a tenth of a minute on the no-ROSC figure. The page uses 24.6, which is the figure the abstract carries, and nothing in the argument turns on which is right."}, "salon-case": {"c": "The hundred-minute case: a 70-year-old man, arrest on a neurology ward, one episode of ventricular fibrillation with unsuccessful defibrillation, then narrow-complex pulseless electrical activity for about an hour with intermittent return of spontaneous circulation throughout; alteplase 5 mg bolus then 45 mg by infusion given near the end, with conversion to sinus rhythm about two minutes after the infusion started; extensive bilateral emboli confirmed; survived without major neurological sequelae after about three months of renal replacement therapy and an occipital infarct", "s": "Wu JP, Gu DY, Wang S, Zhang ZJ, Zhou JC, Zhang RF. Good neurological recovery after rescue thrombolysis of presumed pulmonary embolism despite prior 100 minutes CPR. Journal of Thoracic Disease 2014;6(12):E289-E293", "u": "https://jtd.amegroups.org/article/view/3595/html", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "Read in full precisely because it is cited in support of the recommendation and is usually quoted only as 'survived after 100 minutes of CPR'. The intermittent return of circulation and the two-minute response to the drug are both in the published report, and both cut against the use the case is put to. That reading is mine; the facts are the authors'."}, "salon-troica": {"c": "TROICA: 827 patients with witnessed out-of-hospital arrest of presumed cardiac origin randomised to tenecteplase or placebo during CPR; 30-day survival 18.2% against 20.2% (p=0.51); hospital admission 59.0% against 59.5%; stopped early for futility on the recommendation of the data safety monitoring board", "s": "Boettiger BW, Arntz HR, Chamberlain DA and colleagues, Thrombolysis during resuscitation for out-of-hospital cardiac arrest, New England Journal of Medicine 2008;359(25):2651-62, as recorded in the American College of Cardiology trial summary", "u": "https://www.acc.org/Latest-in-Cardiology/Clinical-Trials/2013/05/30/16/42/TROICA", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "salon-rv": {"c": "In pigs arrested by pulmonary embolism, hypoxia or primary arrhythmia, the right ventricle dilated in all three groups: about 32 mm in the embolism group against 23 mm (hypoxia) and 25 mm (arrhythmia). Clinicians with focused echocardiography training separated the groups with 79% sensitivity and 68% specificity", "s": "Aagaard R, Caap P, Hansson NC, Botker MT, Granfeldt A, Lofgren B. Detection of Pulmonary Embolism During Cardiac Arrest - Ultrasonographic Findings Should Be Interpreted With Caution. Critical Care Medicine 2017;45(7):e695-e702. Twenty-four anaesthetised pigs, arrest untreated for 7 minutes before resuscitation", "u": "https://ouci.dntb.gov.ua/works/42kLxwWl", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "A porcine study, and the page says so in the text as well as here. It is the cleanest available test of the question, because the three arrest aetiologies cannot be randomised in people, but it is animal data and the sensitivity and specificity figures should not be carried across to human practice as though they were measured there."}, "salon-haca": {"c": "HACA, 2002: 275 patients randomised to 32-34 degrees for 24 hours or normothermia after out-of-hospital arrest; favourable neurological outcome at six months 55% against 39%, relative risk 1.40 (95% CI 1.08-1.81), p=0.009; stopped early for slow enrolment and funding", "s": "Hypothermia after Cardiac Arrest Study Group. Mild therapeutic hypothermia to improve the neurologic outcome after cardiac arrest. New England Journal of Medicine 2002;346(8):549-556", "u": "https://criticalcarereviews.com/foundational-trials/haca-trial", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "salon-bernard": {"c": "Bernard, 2002: 77 patients with out-of-hospital ventricular fibrillation arrest and persistent coma after return of circulation, randomised to 33 degrees for 12 hours or normothermia; favourable discharge destination 49% against 26% (p=0.046)", "s": "Bernard SA, Gray TW, Buist MD and colleagues. Treatment of comatose survivors of out-of-hospital cardiac arrest with induced hypothermia. New England Journal of Medicine 2002;346(8):557-63", "u": "https://clincalc.com/blog/2013/10/bernard-2002-australian-hypothermia-study-for-out-of-hospital-arrest/", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": "The page names Bernard and the number of patients but not the city. The source consulted does not state where the trial ran, so the page does not either."}, "salon-ttm": {"c": "TTM, 2013: 939 patients randomised to 33 degrees (473) or 36 degrees (466) after out-of-hospital arrest; all-cause mortality 50% against 48% (p=0.51)", "s": "Nielsen N, Wetterslev J, Cronberg T and colleagues, on behalf of the TTM Trial Investigators. Targeted Temperature Management at 33 degrees C Versus 36 degrees C After Cardiac Arrest. New England Journal of Medicine 2013;369:2197-2206, as recorded in the American College of Cardiology trial summary. Death or poor neurological function at 180 days gave a hazard ratio of 1.02 (p=0.78)", "u": "https://www.acc.org/Latest-in-Cardiology/Clinical-Trials/2013/12/05/22/12/TTM", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "salon-ttm2": {"c": "TTM2, 2021: 1,900 randomised and 1,861 analysed, hypothermia to 33 degrees against targeted normothermia with early fever treatment; death at six months 50% (465/925) against 48% (446/925), relative risk 1.04 (95% CI 0.94-1.14), p=0.37", "s": "Dankiewicz J, Cronberg T, Lilja G and colleagues. Hypothermia versus Normothermia after Out-of-Hospital Cardiac Arrest. New England Journal of Medicine 2021;384(24):2283-2294. Arrhythmia causing haemodynamic compromise was commoner with hypothermia, 24% against 17%", "u": "https://criticalcarereviews.com/foundational-trials/ttm2-trial", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "salon-proseva": {"c": "PROSEVA, 2013: 474 patients with severe ARDS, a PaO2:FiO2 ratio below 150 on FiO2 at least 0.6, proned for at least 16 consecutive hours; 28-day mortality 16% against 32.8% (p<0.001), adjusted odds ratio 0.42 (95% CI 0.26-0.66)", "s": "Guerin C and colleagues, for the PROSEVA Study Group. Prone Positioning in Severe Acute Respiratory Distress Syndrome. New England Journal of Medicine 2013;368:2159-68", "u": "https://www.thebottomline.org.uk/summaries/icm/proseva-study-group-prone-positioning-in-severe-acute-respiratory-distress-syndrome/", "d": "3 November 2026", "r": "November 2027", "v": "confirmed", "n": ""}, "str-wakeup": {"c": "For a wake-up stroke, onset is taken as the estimated midpoint of sleep", "s": "the American Heart Association's own Top Things to Know summary of the 2026 AHA/ASA Guideline for the Early Management of Patients With Acute Ischemic Stroke (Stroke, published online 26 January 2026, doi:10.1161/STR.0000000000000513), which puts the extended window at up to 9 hours from the midpoint of sleep for stroke of unknown onset", "u": "https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know", "d": "6 November 2026", "r": "November 2027", "v": "flagged", "n": "The guideline itself is behind ahajournals.org, which could not be fetched, so this is the AHA's own summary of its own document. Two further independent readings of the guideline agree with the wording. The presentation cited it as an August 2026 paper in a neurology journal; it is in Stroke, in January."}, "str-9h": {"c": "Thrombolysis may be extended beyond 4.5 hours to 9 hours in selected patients", "s": "the American Heart Association's own Top Things to Know summary of the 2026 AHA/ASA Guideline for the Early Management of Patients With Acute Ischemic Stroke (Stroke, published online 26 January 2026, doi:10.1161/STR.0000000000000513), which supports thrombolysis from 4.5 to 9 hours, and in stroke of unknown onset, where advanced imaging shows a perfusion or diffusion mismatch", "u": "https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know", "d": "6 November 2026", "r": "November 2027", "v": "flagged", "n": "The guideline itself is behind ahajournals.org, which could not be fetched, so this is the AHA's own summary of its own document. Two further independent readings of the guideline agree with the wording. The presentation cited it as an August 2026 paper in a neurology journal; it is in Stroke, in January."}, "str-bp140": {"c": "Lowering the systolic blood pressure below 140 mmHg is not recommended, even after complete reperfusion", "s": "the American Heart Association's own Top Things to Know summary of the 2026 AHA/ASA Guideline for the Early Management of Patients With Acute Ischemic Stroke (Stroke, published online 26 January 2026, doi:10.1161/STR.0000000000000513), which states that intensive lowering below 140 mmHg does not improve functional outcome after intravenous thrombolysis and may cause harm after endovascular therapy, including after TICI 3 reperfusion", "u": "https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know", "d": "6 November 2026", "r": "November 2027", "v": "flagged", "n": "The guideline itself is behind ahajournals.org, which could not be fetched, so this is the AHA's own summary of its own document. Two further independent readings of the guideline agree with the wording. The presentation cited it as an August 2026 paper in a neurology journal; it is in Stroke, in January."}, "str-basilar": {"c": "Endovascular therapy improves functional outcome in basilar artery occlusion presenting within 24 hours with an NIHSS of 10 or more", "s": "the American Heart Association's own Top Things to Know summary of the 2026 AHA/ASA Guideline for the Early Management of Patients With Acute Ischemic Stroke (Stroke, published online 26 January 2026, doi:10.1161/STR.0000000000000513), which gives a strong recommendation for endovascular therapy in basilar artery occlusion within 24 hours of onset with an NIHSS of 10 or above", "u": "https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know", "d": "6 November 2026", "r": "November 2027", "v": "flagged", "n": "The guideline itself is behind ahajournals.org, which could not be fetched, so this is the AHA's own summary of its own document. The presentation cited it as an August 2026 paper in a neurology journal; it is in Stroke, in January."}, "str-sich": {"c": "Symptomatic haemorrhagic transformation occurs in about 6% of patients given intravenous thrombolysis", "s": "Hong, Kim and Kim, 'Hemorrhagic Transformation After Ischemic Stroke: Mechanisms and Management', Frontiers in Neurology 2021;12:703258, which states that large parenchymal haematoma and symptomatic intracerebral haemorrhage occur in up to 6% after intravenous thrombolysis", "u": "https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2021.703258/full", "d": "6 November 2026", "r": "November 2028", "v": "confirmed", "n": "This is the review the presentation itself cites. The companion figures on the page — about 5% overall, 89% of them petechial, and 0.6 to 3% without thrombolysis — are not in it and remain as given in the presentation."}, "str-pcc": {"c": "Prothrombin complex concentrate for warfarin reversal in life-threatening bleeding: 50 units/kg, to a maximum of 5000 units", "s": "Australian Red Cross Lifeblood, Warfarin reversal, which gives Beriplex P/N at 50 IU/kg for life-threatening or critical organ bleeding with the weight capped at 100 kg — a ceiling of 5000 IU — together with 5 to 10 mg of intravenous vitamin K", "u": "https://www.lifeblood.com.au/health-professionals/clinical-practice/clinical-indications/warfarin-reversal", "d": "6 November 2026", "r": "November 2027", "v": "confirmed", "n": "The cap is expressed as a weight ceiling rather than a dose ceiling, which comes to the same 5000 units the presentation gives. Vitamin K is given with it and is easily forgotten."}, "str-lytics": {"c": "Alteplase 0.9 mg/kg to a maximum of 90 mg, 10% as a bolus and the rest over 60 minutes; or tenecteplase 0.25 mg/kg to a maximum of 25 mg as a single dose, with the 2026 guideline endorsing either and preferring neither", "s": "the University of Illinois at Chicago drug information group's review of the 2026 AHA/ASA guideline, which gives both doses in exactly these terms and states that for eligible adults presenting within 4.5 hours the guideline endorses either drug, where the previous guideline primarily endorsed alteplase", "u": "https://dig.pharmacy.uic.edu/faqs/2026-2/april-2026-faqs/update-what-are-major-pharmacotherapy-updates-from-the-2026-aha-asa-stroke-guidelines/", "d": "6 November 2026", "r": "November 2027", "v": "flagged", "n": "The guideline itself is behind ahajournals.org, which could not be fetched. The doses are long-standing and match Australian practice; what is new is that neither agent is now preferred over the other."}, "str-driving": {"c": "After a stroke: no private driving for four weeks, three months for a commercial licence, medical clearance before returning in either case", "s": "Stroke Foundation (Australia), Driving after stroke, which gives at least four weeks for a private licence and three months for a commercial one, with medical clearance required before returning, and two weeks (four, commercial) after a transient ischaemic attack. The underlying standard is Austroads, Assessing Fitness to Drive", "u": "https://strokefoundation.org.au/what-we-do/for-survivors-and-carers/after-stroke-factsheets/driving-fact-sheet", "d": "6 November 2026", "r": "November 2027", "v": "corrected", "n": "The presentation gave three weeks for a private licence. The Australian standard is four. This is the one number on the page that was changed rather than attributed, because a patient told three weeks would be driving unlicensed and uninsured in the fourth."}, "ext-wipo-share": {"c": "Weaning-induced pulmonary oedema accounted for 59 per cent of weaning failures (75 of 128 failed spontaneous breathing trials, across 283 trials in 81 patients)", "s": "Liu J et al, Cardiac dysfunction induced by weaning from mechanical ventilation: incidence, risk factors and effects of fluid removal, Critical Care 2016;20:369. Single-centre observational study", "u": "https://link.springer.com/content/pdf/10.1186/s13054-016-1533-9.pdf", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "ext-wipo-risk": {"c": "Independent risk factors for weaning-induced pulmonary oedema: COPD odds ratio 8.7 (95% CI 2.0-37.3), structural cardiopathy 4.5 (1.4-14.1), obesity 3.6 (1.2-12.6)", "s": "Liu J et al, Critical Care 2016;20:369. The authors describe the obesity association as weaker than the other two and in need of confirmation", "u": "https://link.springer.com/content/pdf/10.1186/s13054-016-1533-9.pdf", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "ext-diaphragm": {"c": "Diaphragm dysfunction at weaning: reported incidence 23 to 80 per cent depending on population and method; 29 per cent by ultrasound at first spontaneous breathing trial, 63 per cent by phrenic nerve stimulation in unselected patients", "s": "Dres M and Demoule A, Diaphragm dysfunction during weaning from mechanical ventilation, Critical Care 2018;22:73, citing Kim et al and Dres et al", "u": "https://link.springer.com/article/10.1186/s13054-018-1992-2", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "ext-reintubation-mortality": {"c": "Hospital mortality 18 per cent in reintubated patients against 3 per cent in those never reintubated; adjusted odds ratio 5.86 (95% CI 3.87-8.89). 19 per cent reintubated at some point, 11 per cent within 48 hours", "s": "Cohort of 2,007 patients reported in Respiratory Care 2012;57:1555. The authors caution this is association, not proof of causation, and that reintubation partly marks greater severity", "u": "https://rc.rcjournal.com/content/57/10/1555", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "ext-niv-rescue": {"c": "Non-invasive ventilation for established post-extubation respiratory failure: reintubation 48 per cent in both arms; median time from failure to intubation 2.5 hours with usual care against 12 hours with NIV; ICU mortality 14 against 25 per cent (RR 1.78, 95% CI 1.03-3.20, p=0.048). Trial stopped early", "s": "Esteban A et al, Noninvasive positive-pressure ventilation for respiratory failure after extubation, NEJM 2004;350:2452. Read through a published summary of the trial; the original could not be reached from this environment", "u": "https://www.clinician.com/articles/6105-should-nppv-be-used-in-extubation-failure", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "ext-niv-prophylactic": {"c": "Prophylactic non-invasive ventilation alternating with high-flow nasal oxygen in high-risk patients: reintubation at day 7 11.8 against 18.2 per cent with high-flow alone (difference -6.4 per cent, 95% CI -12.0 to -0.9, p=0.02). ICU mortality 6 against 9 per cent, not significant", "s": "Thille AW et al, JAMA 2019;322:1465. High risk defined as ventilated over 24 hours, passed a spontaneous breathing trial, and over 65 or with underlying cardiac or respiratory disease including obesity hypoventilation", "u": "https://www.clinician.com/articles/146420-preventing-post-extubation-respiratory-failure-can-we-decrease-risk-in-our-high-risk-populations", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "ext-steroid-cuffleak": {"c": "Corticosteroids before extubation in patients selected by a failed cuff leak test: reintubation RR 0.35 (95% CI 0.20-0.64), post-extubation respiratory failure RR 0.34 (0.24-0.48), NNT 5. In unselected patients neither reached significance. The cuff leak test has poor positive predictive value for stridor", "s": "2017 meta-analysis of 11 randomised trials, 2,472 patients. Regimens included methylprednisolone 40 mg 6-hourly for four doses, or a single 40 mg dose 4 hours before extubation", "u": "https://www.clinician.com/articles/140950-prophylactic-steroids-prevent-reintubation-in-patients-at-risk-for-post-extubation-stridor", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "cm-ici-steroid": {"c": "Immune checkpoint inhibitor myocarditis is treated with pulse methylprednisolone 500 to 1000 mg daily for three to five days", "s": "ESC/EHA/ESTRO/IC-OS cardio-oncology guidance as summarised in Cardiovascular Diagnosis and Therapy, 'Therapeutic agents for steroid-refractory immune checkpoint inhibitor-related myocarditis'. ESMO gives three days; NCCN and SITC give 1 g for three to five", "u": "https://cdt.amegroups.org/article/view/127481/html", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "cm-ici-refractory": {"c": "What proportion of immune checkpoint inhibitor myocarditis is steroid-refractory", "s": "No population-level estimate exists: the review states that no studies have estimated the incidence of steroid-refractory disease, and the only figure available is a single-centre series of 24 patients in which 16 (67 per cent) were corticosteroid-resistant. This page previously said 'up to half', which was not supported by anything, and has been reworded", "u": "https://cdt.amegroups.org/article/view/127481/html", "d": "11 November 2026", "r": null, "v": "flagged", "n": ""}, "nn-adrenaline": {"c": "Adrenaline 10 to 30 micrograms/kg intravenously, which is 0.1 to 0.3 mL/kg of 1:10,000, repeated every 3 to 5 minutes while the heart rate stays below 60. The endotracheal dose is higher at 50 to 100 micrograms/kg, and the umbilical vein is the suggested route", "s": "ANZCOR neonatal guidelines 13.1 to 13.8, collected edition", "u": "https://www.resus.org.nz/assets/Uploads/Neonatal-Resuscitation-All-Guidelines.pdf", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "nn-volume": {"c": "Volume expansion 10 mL/kg of isotonic crystalloid, for suspected blood loss or shock that has not responded to other measures, given over several minutes and repeated after reassessment", "s": "ANZCOR neonatal guidelines 13.1 to 13.8, collected edition", "u": "https://www.resus.org.nz/assets/Uploads/Neonatal-Resuscitation-All-Guidelines.pdf", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "nn-glucose": {"c": "Target blood glucose at least 2.6 mmol/L, with an intravenous bolus of 2 mL/kg of 10 per cent dextrose. Note that a cooled baby is managed to a higher range, 3 to 7 mmol/L", "s": "WA Child and Adolescent Health Service / NETS WA, Hypoglycaemia", "u": "https://pch.health.wa.gov.au/~/media/HSPs/CAHS/Documents/Health-Professionals/NETS/Hypoglycaemia.pdf", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "nn-cooling": {"c": "Therapeutic hypothermia for moderate or severe hypoxic-ischaemic encephalopathy at 35 weeks or more and under 6 hours of age. The full NSW criteria add a weight of at least 1,800 g and evidence of perinatal depression — pH below 7.00, base excess -12 or worse, Apgar under 6 at 10 minutes, or resuscitation lasting 10 minutes or more", "s": "NSW Agency for Clinical Innovation, Hypoxic ischaemic encephalopathy in newborns", "u": "https://aci.health.nsw.gov.au/__data/assets/pdf_file/0008/885257/ACI-Hypoxic-ischaemic-encephalopathy-in-newborns.pdf", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}, "nn-pge": {"c": "Alprostadil from 10 nanograms/kg/min, range 5 to 50. Doses of 50 or more may be needed to resuscitate an infant with poor perfusion and oxygenation, or where the duct is constricting or already closed. Maintenance is then the lowest dose that holds it open, usually 3 to 20", "s": "Royal Hospital for Women neonatal formulary, Alprostadil v3.0, September 2025", "u": "https://www.seslhd.health.nsw.gov.au/sites/default/files/groups/Royal_Hospital_for_Women/Neonatal/Neomed/Alprostadil_ANMFv3.0_20250925.pdf", "d": "11 November 2026", "r": null, "v": "confirmed", "n": ""}};
  var P = {"drugstore-01-adrenaline.html": {"d": "23 October 2026", "r": "October 2027", "n": 6, "f": 0}, "drugstore-02-paracetamol.html": {"d": "23 October 2026", "r": "October 2027", "n": 8, "f": 0}, "drugstore-04-pantoprazole.html": {"d": "3 November 2026", "r": "November 2027", "n": 41, "f": 2}, "salon-01-ninety-minutes.html": {"d": "3 November 2026", "r": "November 2027", "n": 13, "f": 0}, "podcast-61-scad.html": {"d": "26 October 2026", "r": "October 2027", "n": 11, "f": 2}, "mnemonic-59-cardio-stress.html": {"d": "11 November 2026", "r": "October 2027", "n": 18, "f": 3}, "mnemonic-60-extubation.html": {"d": "11 November 2026", "r": null, "n": 7, "f": 0}, "exam-cicm-first-03-the-mcq-paper.html": {"d": "28 October 2026", "r": "October 2027", "n": 9, "f": 1}};

  var css = document.createElement("style");
  css.textContent =
    "sup.vf{font:600 10px 'Helvetica Neue',Arial,sans-serif;color:#2E6473;" +
      "cursor:pointer;margin-left:2px;vertical-align:super;line-height:0;" +
      "border:0;background:none;padding:0 1px}" +
    "sup.vf::after{content:'\\2713'}" +
    "sup.vf:hover,sup.vf.open{color:#A8442A}" +
    /* A mind map keeps its claims inside its SVG, where a <sup> cannot
       go and ::after is never rendered. The tick is therefore a real
       <text> carrying the check character; only colour and cursor
       come from here. Document CSS does style inline SVG. */
    "text.vf,tspan.vf{fill:#2E6473;cursor:pointer;" +
      "font:600 11px 'Helvetica Neue',Arial,sans-serif}" +
    "text.vf:hover,text.vf.open,tspan.vf:hover,tspan.vf.open{fill:#A8442A}" +
    ".vf-card{position:absolute;z-index:60;max-width:340px;background:#FFFFFF;" +
      "border:1px solid #D8D4CA;border-radius:10px;padding:15px 17px;" +
      "box-shadow:0 6px 26px rgba(27,42,51,.16);" +
      "font:400 14.5px/1.5 'Iowan Old Style',Palatino,Georgia,serif;color:#25303A}" +
    ".vf-card b{display:block;font:600 11px 'Helvetica Neue',Arial,sans-serif;" +
      "letter-spacing:.14em;text-transform:uppercase;margin:0 0 7px;color:#2E6473}" +
    ".vf-card .cl{display:block;font-style:italic;margin:0 0 9px;color:#1B2A33}" +
    ".vf-card p{margin:0 0 8px}" +
    ".vf-card p:last-child{margin:0}" +
    ".vf-card .mt{font:400 13px 'Helvetica Neue',Arial,sans-serif;color:#6E6B63}" +
    ".vf-card a{color:#2E6473}" +
    ".vf-band{margin:26px 0 0;padding:13px 17px;background:#EDF2F3;" +
      "border-left:4px solid #2E6473;border-radius:0 7px 7px 0;" +
      "font:400 14px/1.55 'Helvetica Neue',Arial,sans-serif;color:#44525A}" +
    ".vf-band b{color:#2E6473}" +
    "@media print{sup.vf,text.vf,tspan.vf{display:none}.vf-card{display:none}}";
  document.head.appendChild(css);

  var card = null, current = null;
  function close(){
    if(card){ card.remove(); card = null; }
    if(current){ current.classList.remove("open"); current = null; }
  }
  function open(el){
    var v = V[el.getAttribute("data-v")];
    if(!v) return false;
    close();
    var verdict = {confirmed:"Checked and confirmed", corrected:"Checked and corrected",
                   contested:"Checked — genuinely contested",
                   flagged:"Checked — one open question"}[v.v] || "Checked";
    card = document.createElement("div");
    card.innerHTML = "<b>" + verdict + "</b>"
      + "<span class='cl'>" + v.c + "</span>"
      + "<p>Against " + (v.u ? "<a href='" + v.u + "'>" + v.s + "</a>" : v.s)
      + ", on " + v.d + ".</p>"
      + (v.r ? "<p class='mt'>Due for review " + v.r + ".</p>"
             : "<p class='mt'>Settled — no review needed.</p>")
      + (v.n ? "<p class='mt'>" + v.n + "</p>" : "");
    card.className = "vf-card";
    document.body.appendChild(card);
    var r = el.getBoundingClientRect(), w = card.offsetWidth;
    var top = r.bottom + window.scrollY + 8, left = r.left + window.scrollX;
    if(left + w > window.innerWidth - 14) left = window.innerWidth - w - 14;
    if(left < 10) left = 10;
    if(r.bottom + card.offsetHeight + 20 > window.innerHeight)
      top = r.top + window.scrollY - card.offsetHeight - 8;
    /* A tall card flipped upward can finish above the top of the window, which
       hides the claim and the verdict — the two lines the reader opened it for.
       Clamp it: a card taller than the window then runs off the bottom, where
       the page can at least be scrolled to reach it. */
    if(top < window.scrollY + 10) top = window.scrollY + 10;
    card.style.top = top + "px"; card.style.left = left + "px";
    el.classList.add("open"); current = el;
    return true;
  }

  document.addEventListener("click", function(ev){
    var el = ev.target.closest ? ev.target.closest("sup.vf, text.vf, tspan.vf") : null;
    if(el){ ev.preventDefault(); if(current === el) close(); else open(el); return; }
    if(card && !ev.target.closest(".vf-card")) close();
  });
  document.addEventListener("keydown", function(e){ if(e.key === "Escape") close(); });
  window.addEventListener("resize", close);

  /* the page-level band — only for pages where every number has been done */
  var here = location.pathname.split("/").pop() || "index.html";
  var p = P[here];
  if(p){
    /* The mnemonic series is built on .wrap > .card and has no .pad at all,
       so until November 2026 this quietly found no host and no band ever
       appeared on those pages — silently, which is the worst way to fail.
       Fall back to .card, and place the band before a footer when the host
       contains one rather than after it. */
    var host = document.querySelector(".pad:last-of-type")
            || document.querySelector(".pad")
            || document.querySelector(".card");
    if(host){
      var b = document.createElement("div");
      b.className = "vf-band";
      b.innerHTML = "<b>Every number on this page has been checked.</b> " +
        (p.f ? "All " + p.n + " against their sources on " + p.d + " \u2014 " +
               (p.n - p.f) + " against primary sources, and " + p.f +
               " flagged, where the primary could not be read."
             : "All " + p.n + " against primary sources, on " + p.d + ".") +
        (p.r ? " Next review " + p.r + "." : "") +
        " The ticks show what was checked and against what.";
      var foot = host.querySelector(":scope > footer");
      if(foot){ host.insertBefore(b, foot); } else { host.appendChild(b); }
    }
  }
})();
